package com.bank.routing.model;

// A desk holding one digit of a routing number.
public class RoutingNode {
    private final int digit; // 0..9
    private RoutingNode left;
    private RoutingNode right;

    public RoutingNode(int digit) { this.digit = digit; }
    public int getDigit() { return digit; }
    public RoutingNode getLeft() { return left; }
    public RoutingNode getRight() { return right; }
    public void setLeft(RoutingNode left) { this.left = left; }
    public void setRight(RoutingNode right) { this.right = right; }
    public boolean isLeaf() { return left == null && right == null; }
}
