package com.bank.routing.service;

import com.bank.routing.model.RoutingNode;
import java.util.logging.Logger;

// Sums every root-to-leaf routing number built digit by digit.
public class PathNumberService {
    private static final Logger log = Logger.getLogger(PathNumberService.class.getName());

    public long sumAllRoutingNumbers(RoutingNode root) {
        return dfs(root, 0L);
    }

    private long dfs(RoutingNode node, long running) {
        if (node == null) {
            return 0L;
        }
        // Shift left one decimal place and append this digit (use long).
        long next = running * 10 + node.getDigit();
        if (node.isLeaf()) {
            log.info(() -> "Completed routing number: " + next);
            return next;
        }
        // Internal node: a null child contributes 0.
        return dfs(node.getLeft(), next) + dfs(node.getRight(), next);
    }
}
