package com.bank.routing;

import com.bank.routing.model.RoutingNode;
import com.bank.routing.service.PathNumberService;
import java.util.logging.Logger;

public class PathNumberApplication {
    private static final Logger log = Logger.getLogger(PathNumberApplication.class.getName());

    public static void main(String[] args) {
        // Routing tree: root 1 ; children 7 and 9 ; leaves under 7 are 2 and 5.
        //   path 1-7-2 = 172, path 1-7-5 = 175, path 1-9 = 19
        RoutingNode root = new RoutingNode(1);
        RoutingNode seven = new RoutingNode(7);
        RoutingNode nine = new RoutingNode(9);
        RoutingNode two = new RoutingNode(2);
        RoutingNode five = new RoutingNode(5);

        root.setLeft(seven);
        root.setRight(nine);
        seven.setLeft(two);
        seven.setRight(five);

        PathNumberService service = new PathNumberService();
        long total = service.sumAllRoutingNumbers(root);
        log.info("Total of all routing numbers (NBI reconciliation): " + total);
    }
}
